const b = $input.first().json.body ?? {};
const message = typeof b.message === 'string' ? b.message.trim() : '';
const sessionId = typeof b.sessionId === 'string' && /^[a-zA-Z0-9_-]{8,128}$/.test(b.sessionId) ? b.sessionId : '';
const history = Array.isArray(b.history) ? b.history.slice(-6).filter(x => x && ['user','assistant'].includes(x.role) && typeof x.content === 'string').map(x => ({role:x.role,content:x.content.slice(0,1000)})) : [];
const inputCatalog = b.context?.catalog;
function short(v,max=160){ return typeof v === 'string' ? v.slice(0,max) : ''; }
function number(v){ if(v===null||v===undefined||v===''||typeof v==='boolean')return null; const n=Number(v); return Number.isFinite(n) && n>=0 && n<=1000000000 ? n : null; }
function asArray(value){return Array.isArray(value) ? value : []}
const tours = asArray(inputCatalog?.tours).slice(0,40).map(t=>({
 id:short(t.id,80),title:short(t.title,150),destination:short(t.destination,100),
 days:number(t.days),cost:number(t.cost),carbon:number(t.carbon),description:short(t.description,240),
 rating:number(t.rating),url:short(t.url,250),tags:asArray(t.tags).slice(0,6).map(x=>short(x,40))
})).filter(t=>t.id&&t.title);
function normalizeServices(value){ return asArray(value).filter(s=>s?.status==='active').slice(0,40).map(s=>({
 id:short(s.id,80),name:short(s.name,150),type:short(s.type,40),destination:short(s.destination,100),
 cost:number(s.cost),carbon:number(s.carbon),rating:number(s.rating),status:'active',url:short(s.url,250)
})).filter(s=>s.id&&s.name); }
const services = normalizeServices(inputCatalog?.services);
const serviceCandidates = normalizeServices(inputCatalog?.serviceCandidates);
const normalizedIntentMessage=message.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\u0111\u0110]/g,'d').toLowerCase();
function classifyIntent(value){
 const normalized=String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\u0111\u0110]/g,'d').toLowerCase();
 if(/backend intent: custom_itinerary/.test(normalized))return 'itinerary';
 const hasPlanAction=/\b(?:lap|tao|len|xay dung|thiet ke|lam|sap xep|soan)\b/.test(normalized);
 const mentionsPlan=/\b(?:lich(?: trinh| di)?|hanh trinh|ke hoach(?: du lich| chuyen di)?)\b/.test(normalized)||(hasPlanAction&&/\btour\b/.test(normalized));
 const asksForPlan=/\b(?:goi y|de xuat|tu van|muon)\b/.test(normalized);
 const explicitTourSearch=/\btour\b/.test(normalized)&&/\b(?:tim|goi y|de xuat|so sanh|chon|tu van|muon)\b/.test(normalized);
 if(mentionsPlan&&(hasPlanAction||(asksForPlan&&!explicitTourSearch)))return 'itinerary';
 return explicitTourSearch?'tour_search':'';
}
const currentIntent=classifyIntent(message);
const latestHistoryIntent=[...history].reverse().filter(item=>item.role==='user').map(item=>classifyIntent(item.content)).find(Boolean)||'';
const lastAssistantText=[...history].reverse().find(item=>item.role==='assistant')?.content||'';
const normalizedAssistantText=String(lastAssistantText).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[\u0111\u0110]/g,'d').toLowerCase();
const answersDuration=/\b\d{1,2}\s*(?:ngay|day|dem|night)\b/.test(normalizedIntentMessage);
const answersItineraryClarification=/ban muon di (?:.{1,50} )?(?:trong bao lau|bao nhieu ngay)|ban muon lap lich trinh o dau|ban muon den diem den nao|chon mot diem den|chon thoi luong/.test(normalizedAssistantText);
const itineraryContinuation=latestHistoryIntent==='itinerary'&&(answersDuration||answersItineraryClarification);
const requestIntent=b.requestIntent==='itinerary'||currentIntent==='itinerary'||itineraryContinuation?'itinerary':b.requestIntent==='tour_search'||currentIntent==='tour_search'?'tour_search':'general';
const valid = message.length>0 && message.length<=4000 && !!sessionId;
return [{json:{valid,message,requestIntent,sessionId,history,
 catalog:{tours:inputCatalog?.available===true?tours:[],services:inputCatalog?.available===true?services:[],serviceCandidates:inputCatalog?.available===true?serviceCandidates:[],serviceCandidatesComplete:inputCatalog?.serviceCandidatesComplete===true,serviceCandidatesPage:Number.isInteger(inputCatalog?.serviceCandidatesPage)&&inputCatalog.serviceCandidatesPage>0?Math.min(inputCatalog.serviceCandidatesPage,2):1,serviceCandidatesNextPage:Number.isInteger(inputCatalog?.serviceCandidatesNextPage)&&inputCatalog.serviceCandidatesNextPage>0?Math.min(inputCatalog.serviceCandidatesNextPage,3):null,available:inputCatalog?.available===true,fetchedAt:short(inputCatalog?.fetchedAt,40),page:Number.isInteger(inputCatalog?.page)&&inputCatalog.page>0?Math.min(inputCatalog.page,10000):1,pageSize:Number.isInteger(inputCatalog?.pageSize)&&inputCatalog.pageSize>0?Math.min(inputCatalog.pageSize,40):20,nextPage:Number.isInteger(inputCatalog?.nextPage)&&inputCatalog.nextPage>0?Math.min(inputCatalog.nextPage,10000):null,truncated:inputCatalog?.truncated===true,truncatedTours:inputCatalog?.truncatedTours===true,truncatedServices:inputCatalog?.truncatedServices===true},
 error:valid?'':(!sessionId?'sessionId phải có 8-128 ký tự a-z A-Z 0-9 _ -':'message phải dài từ 1 đến 4000 ký tự')}}];

const ai = $input.first().json;
const input = $('Validate Input1').first().json;
const startedAt = $('AI Start1').first().json._aiStartedAt;
const agentMs = Math.max(0, Date.now() - Number(startedAt || Date.now()));

let output = typeof ai.output === 'string' ? ai.output.trim() : '';
const iterationLimited = /^Agent stopped due to max iterations\.?$/i.test(output);

if (iterationLimited) output = '';

const reason = ai.finishReason ?? ai.response_metadata?.finishReason;
const outputLimited = reason === 'MAX_TOKENS';

if (outputLimited && output) {
  output += '\n\n_Lượt trả lời đã chạm giới hạn độ dài. Bạn có thể yêu cầu viết tiếp phần còn thiếu._';
}

console.log(JSON.stringify({
  event: 'greensteps_n8n_agent_performance',
  agentMs,
  success: Boolean(output)
}));

return [{
  json: {
    success: Boolean(output),
    output,
    ...(iterationLimited ? { code: 'CHAT_ITERATION_LIMIT' } : {}),
    sessionId: input.sessionId,
    mode: 'n8n-gemini-agent-v3',
    outputLimited,
    performance: { agentMs }
  }
}];

const toolStarted = Date.now();
try {
  const data = $("Validate Input1").first().json;
  const args = typeof query === "object" && query !== null ? query : (() => { try { return JSON.parse(query); } catch { return { search: String(query ?? "") }; } })();
  const norm = value => String(value ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[\u0111\u0110]/g, "d").toLowerCase().trim();
  const catalog = data.catalog ?? { available: false, tours: [], truncatedTours: false, nextPage: null };
  if (!catalog.available) return JSON.stringify({ status: "catalog_unavailable", message: "Backend catalog is unavailable; no GreenSteps data was verified." });
  const rows = Array.isArray(catalog.tours) ? catalog.tours : [];
  const search = norm(args.search ?? "");
  const maxBudget = args.maxBudget === undefined || args.maxBudget === null || args.maxBudget === "" ? null : Number(args.maxBudget);
  const days = args.days === undefined || args.days === null || args.days === "" ? null : Number(args.days);
  if (maxBudget !== null && (!Number.isFinite(maxBudget) || maxBudget < 0)) return JSON.stringify({ status: "invalid_query" });
  if (days !== null && (!Number.isInteger(days) || days < 1 || days > 14)) return JSON.stringify({ status: "invalid_query" });
  const matches = rows.filter(tour => {
    const searchable = norm([tour.title, tour.destination, tour.description].join(" "));
    return (!search || searchable.includes(search))
      && (maxBudget === null || (tour.cost !== null && tour.cost !== undefined && Number(tour.cost) <= maxBudget))
      && (days === null || Number(tour.days) === days);
  });
  const more = catalog.truncatedTours === true && Number(catalog.nextPage) > Number(catalog.page || 1);
  const results = matches.slice(0, 8);
  return JSON.stringify({ status: results.length ? (more ? "partial" : "ok") : (more ? "partial_no_match" : "not_found"), matches: results, totalMatches: matches.length, matchesOnPage: matches.length, listedOnly: true, searchComplete: !more, noMatchStatus: results.length ? null : (more ? "not_found_in_current_page" : "not_found_in_complete_catalog"), page: catalog.page, nextPage: more ? catalog.nextPage : null, truncated: more, fetchedAt: catalog.fetchedAt ?? "" });
} catch {
  return JSON.stringify({ status: "error", code: "TOUR_SEARCH_FAILED", message: "Catalog search failed." });
} finally {
  console.log(JSON.stringify({ event: "greensteps_n8n_tool_performance", tool: "search_tours", durationMs: Date.now() - toolStarted }));
}

const toolStarted = Date.now();
try {
  const data = $("Validate Input1").first().json;
  const args = typeof query === "object" && query !== null ? query : (() => { try { return JSON.parse(query); } catch { return { search: String(query ?? "") }; } })();
  const norm = value => String(value ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[\u0111\u0110]/g, "d").toLowerCase().trim();
  const catalog = data.catalog ?? { available: false, services: [], truncatedServices: false, nextPage: null };
  if (!catalog.available) return JSON.stringify({ status: "catalog_unavailable", message: "Backend catalog is unavailable; no GreenSteps data was verified." });
  const itineraryCandidates = data.requestIntent === "itinerary";
  const rows = Array.isArray(itineraryCandidates ? catalog.serviceCandidates : catalog.services) ? (itineraryCandidates ? catalog.serviceCandidates : catalog.services) : [];
  const search = norm(args.search ?? "");
  const destination = norm(args.destination ?? "");
  const rawType = norm(args.type ?? "");
  const typeAliases = { "homestay": "stay", "khach san": "stay", "luu tru": "stay", "lodging": "stay", "an uong": "food", "nha hang": "food", "ca phe": "food", "cafe": "food", "dining": "food", "di chuyen": "transport", "van chuyen": "transport", "tham quan": "attraction" };
  const type = typeAliases[rawType] ?? rawType;
  const maxBudget = args.maxBudget === undefined || args.maxBudget === null || args.maxBudget === "" ? null : Number(args.maxBudget);
  if (maxBudget !== null && (!Number.isFinite(maxBudget) || maxBudget < 0)) return JSON.stringify({ status: "invalid_query" });
  const matches = rows.filter(service => {
    const searchable = norm([service.name, service.destination, service.type].join(" "));
    return service.status === "active" && (!search || searchable.includes(search))
      && (!destination || norm(service.destination).includes(destination))
      && (!type || norm(service.type) === type)
      && (maxBudget === null || (service.cost !== null && service.cost !== undefined && Number(service.cost) <= maxBudget));
  });
  const more = itineraryCandidates ? catalog.serviceCandidatesComplete !== true : catalog.truncatedServices === true && Number(catalog.nextPage) > Number(catalog.page || 1);
  const page = itineraryCandidates ? Number(catalog.serviceCandidatesPage || 1) : Number(catalog.page || 1);
  const nextPage = more ? (itineraryCandidates ? Number(catalog.serviceCandidatesNextPage || page + 1) : Number(catalog.nextPage)) : null;
  const results = matches.slice(0, 8);
  return JSON.stringify({ status: results.length ? (more ? "partial" : "ok") : (more ? "partial_no_match" : "not_found"), matches: results, totalMatches: matches.length, matchesOnPage: matches.length, listedOnly: true, searchComplete: !more, noMatchStatus: results.length ? null : (more ? "not_found_in_current_page" : "not_found_in_complete_catalog"), page, nextPage, truncated: more, fetchedAt: catalog.fetchedAt ?? "" });
} catch {
  return JSON.stringify({ status: "error", code: "SERVICE_SEARCH_FAILED", message: "Catalog search failed." });
} finally {
  console.log(JSON.stringify({ event: "greensteps_n8n_tool_performance", tool: "search_services", durationMs: Date.now() - toolStarted }));
}

const data = $("Validate Input1").first().json;
const catalog = data.catalog ?? { available: false, tours: [], services: [] };
if (!catalog.available) return JSON.stringify({ status: "catalog_unavailable", destinations: [] });
const norm = value => String(value ?? "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[\u0111\u0110]/g, "d").toLowerCase().trim();
const args = typeof query === "object" && query !== null ? query : (() => { try { return JSON.parse(query); } catch { return { search: String(query ?? "") }; } })();
const search = norm(args.search ?? "");
const names = [...new Set([...catalog.tours, ...catalog.services].map(row => row.destination).filter(value => typeof value === "string" && value.trim()).filter(value => !search || norm(value).includes(search)))].sort((a,b) => a.localeCompare(b,"vi"));
const more = catalog.truncated === true && Number(catalog.nextPage) > Number(catalog.page || 1);
const results = names.slice(0,30);
return JSON.stringify({ status: results.length ? (more ? "partial" : "ok") : (more ? "partial_no_match" : "not_found"), destinations: results, totalMatches: names.length, page: catalog.page, nextPage: more ? catalog.nextPage : null, truncated: more, searchComplete: !more, noMatchStatus: results.length ? null : (more ? "not_found_in_current_page" : "not_found_in_complete_catalog"), fetchedAt: catalog.fetchedAt ?? "" });

const toolStarted = Date.now();

try {
  // Nhận tham số từ AI Agent
  let args = {};

  if (typeof query === "object" && query !== null) {
    args = query;
  } else if (typeof query === "string") {
    try {
      args = JSON.parse(query);
    } catch {
      args = {};
    }
  }

  const items = Array.isArray(args.items)
    ? args.items
    : [];

  // Kiểm tra số lượng hạng mục
  if (items.length === 0 || items.length > 20) {
    return JSON.stringify({
      status: "invalid_items",
      message: "Danh sách phải có từ 1 đến 20 hạng mục."
    });
  }

  let total = 0;
  const lines = [];

  for (const item of items) {
    const name = String(item?.name ?? "").trim();
    const rawCost = item?.unitCost;
    const rawQuantity = item?.quantity;

    const unitCost = Number(rawCost);
    const quantity = Number(rawQuantity);

    // Không cho phép thiếu đơn giá, số lượng hoặc tên
    const invalid =
      !name ||
      rawCost === null ||
      rawCost === undefined ||
      rawCost === "" ||
      typeof rawCost === "boolean" ||
      rawQuantity === null ||
      rawQuantity === undefined ||
      rawQuantity === "" ||
      typeof rawQuantity === "boolean" ||
      !Number.isFinite(unitCost) ||
      !Number.isFinite(quantity) ||
      unitCost < 0 ||
      unitCost > 1000000000 ||
      quantity <= 0 ||
      quantity > 100;

    if (invalid) {
      return JSON.stringify({
        status: "invalid_item",
        message: "Hạng mục có đơn giá hoặc số lượng không hợp lệ.",
        item: name.slice(0, 80)
      });
    }

    const subtotal = Math.round(unitCost * quantity);

    total += subtotal;

    lines.push({
      name: name.slice(0, 80),
      unitCost,
      quantity,
      subtotal
    });
  }

  // Kiểm tra ngân sách
  const rawBudget = args.budget;

  const budget =
    rawBudget === null ||
    rawBudget === undefined ||
    rawBudget === "" ||
    typeof rawBudget === "boolean"
      ? null
      : Number(rawBudget);

  const validBudget =
    budget !== null &&
    Number.isFinite(budget) &&
    budget > 0;

  const remaining = validBudget
    ? Math.round(budget - total)
    : null;

  return JSON.stringify({
    status: "ok",
    currency: "VND",
    items: lines,
    total: Math.round(total),
    budget: validBudget ? budget : null,
    remaining,
    overBudget: validBudget ? remaining < 0 : null,
    notice:
      "Tổng chi phí chỉ bao gồm các hạng mục đã cung cấp. " +
      "Chưa bao gồm những chi phí còn thiếu hoặc chưa được xác minh."
  });

} catch (error) {
  return JSON.stringify({
    status: "error",
    code: "BUDGET_ESTIMATE_FAILED",
    message: "Không thể tính toán ngân sách."
  });

} finally {
  console.log(
    JSON.stringify({
      event: "greensteps_n8n_tool_performance",
      tool: "budget_estimate",
      durationMs: Date.now() - toolStarted
    })
  );
}

const toolStarted = Date.now();

try {
  // Nhận tham số từ AI Agent
  let args = {};

  if (typeof query === "object" && query !== null) {
    args = query;
  } else if (typeof query === "string") {
    try {
      args = JSON.parse(query);
    } catch {
      args = {};
    }
  }

  const items = Array.isArray(args.items)
    ? args.items
    : [];

  if (items.length === 0 || items.length > 20) {
    return JSON.stringify({
      status: "invalid_input",
      message: "Cần từ 1 đến 20 hạng mục phát thải."
    });
  }

  let total = 0;
  const details = [];

  for (const item of items) {
    const rawValue = item?.kgCO2e;

    if (
      rawValue === null ||
      rawValue === undefined ||
      rawValue === "" ||
      typeof rawValue === "boolean"
    ) {
      return JSON.stringify({
        status: "invalid_input",
        message: "Thiếu hoặc sai giá trị phát thải."
      });
    }

    const value = Number(rawValue);

    if (
      !Number.isFinite(value) ||
      value < 0 ||
      value > 100000
    ) {
      return JSON.stringify({
        status: "invalid_input",
        message: "Giá trị kg CO2e không hợp lệ."
      });
    }

    total += value;

    details.push({
      name: String(item?.name ?? "Hạng mục").slice(0, 80),
      kgCO2e: value
    });
  }

  return JSON.stringify({
    status: "ok",
    unit: "kg CO2e",
    items: details,
    total: Math.round(total * 100) / 100,
    notice:
      "Chỉ cộng các khoản phát thải có cùng đơn vị kg CO2e " +
      "và cùng phạm vi đo lường. " +
      "Không bao gồm những khoản chưa có dữ liệu."
  });

} catch (error) {
  return JSON.stringify({
    status: "error",
    code: "CARBON_SUMMARY_FAILED",
    message: "Không thể tính tổng lượng phát thải."
  });

} finally {
  console.log(
    JSON.stringify({
      event: "greensteps_n8n_tool_performance",
      tool: "carbon_summary",
      durationMs: Date.now() - toolStarted
    })
  );
}
